// Prismatic Flutter Logo (Inspired by iOS Prismatic Flow aesthetic)
// A 3D sculptural Flutter logo crafted from iridescent transparent glass
// with sinusoidal oscillating curved fringes, visible back edges, and spotted highlights.

// ============================================================================
// --- CONFIGURATION CONSTANTS (Tweak these to customize shader behavior) -----
// ============================================================================

// --- Glass Transparency & Internal Optics ---
#define GLASS_TRANSPARENCY      0.82    // 0.0 = solid opaque pearlescent, 1.0 = clear transparent glass
#define GLASS_REFRACT_INDEX     1.42    // Refractive index of glass (causes optical bending)
#define BACK_EDGE_INTENSITY     2.5     // Visibility/glint of back edges and overlapping pieces through glass
#define FLUTTER_TINT_AMOUNT     0.10    // Blend amount of Flutter blue tint inside band (0.0 = pure rainbow)
#define FRESNEL_POWER           2.8     // View-angle reflection power (concentrates on edges)

// --- Highlight & Specular Settings ---
#define HIGHLIGHT_INTENSITY     3.5     // Brightness of specular highlight spots
#define HIGHLIGHT_SHARPNESS     80.0    // Specular tightness / glossiness (higher = smaller tighter spots)
#define HIGHLIGHT_SPOTTEDNESS   0.75    // 0.0 = uniform smooth streak, 1.0 = highly concentrated spots
#define HIGHLIGHT_DISPERSION    0.12    // Chromatic dispersion (prism color split) in highlights
#define RIM_GLINT_INTENSITY     3.5     // Razor highlight intensity along curved bevels

// --- Anisotropic Curvature & Iridescence Settings ---
#define IRID_CURVATURE          0.65    // Anisotropic curve bending strength (0.0 = straight line, >0 = curved arc)
#define IRID_HORIZONTAL_SPEED   0.85    // Horizontal oscillation speed (frequency of bouncing back and forth)
#define IRID_HORIZONTAL_SPAN    1.30    // Horizontal travel amplitude / distance across the logo
#define IRID_CURVE_SPEED        0.80    // Speed of dynamic curvature breathing/flexing based on iTime
#define IRID_CURVE_DYNAMIC      0.25    // Amount of dynamic curvature breathing/morphing over time
#define IRID_SPECTRUM_LENGTH    1.8     // Distance/length across logo where all colors are painted (non-repeating)
#define IRID_SATURATION         1.45    // Color saturation boost (1.0 = standard, 1.5+ = rich jewel tones)
#define IRID_SPECTRUM_OFFSET    0.0     // Shift/offset of the spectrum center along the logo
#define IRID_EDGE_FEATHER       0.07    // Softness of transition from rainbow band to clear black glass
#define IRID_FRINGE_INTENSITY   0.08    // Thin-film interference angle shift

// --- 3D Logo Dimensions & Motion ---
#define LOGO_SCALE              1.08    // Size of the Flutter logo in viewport
#define LOGO_THICKNESS          0.080   // Depth/thickness of the glass slabs
#define LOGO_ROUNDNESS          0.032   // Bevel roundness radius of edges
#define LOGO_FLOAT_SPEED        0.40    // Idle floating & tilting speed in 3D

// --- Surface Roughness & Texture Bump (iChannel0) ---
#define ROUGHNESS_INTENSITY     0.025   // 0.0 = polished smooth glass, >0.0 = frosted / textured glass bump
#define ROUGHNESS_SCALE         2.2     // Texture frequency / grain scale across the logo

// --- Background & Bloom ---
#define CORONA_BLOOM_GLOW       0.15    // Luminous chromatic glow around logo on OLED black
#define CORONA_FALLOFF          22.0    // Falloff rate of the background corona
// ============================================================================

mat2 rot2D(float a) {
    float c = cos(a), s = sin(a);
    return mat2(c, -s, s, c);
}

float dot2(vec2 v) {
    return dot(v, v);
}

// Exact 2D distance to a convex quadrilateral
float sdQuad(vec2 p, vec2 v0, vec2 v1, vec2 v2, vec2 v3) {
    vec2 e0 = v1 - v0; vec2 w0 = p - v0;
    vec2 e1 = v2 - v1; vec2 w1 = p - v1;
    vec2 e2 = v3 - v2; vec2 w2 = p - v2;
    vec2 e3 = v0 - v3; vec2 w3 = p - v3;

    vec2 b0 = w0 - e0 * clamp(dot(w0, e0) / dot(e0, e0), 0.0, 1.0);
    vec2 b1 = w1 - e1 * clamp(dot(w1, e1) / dot(e1, e1), 0.0, 1.0);
    vec2 b2 = w2 - e2 * clamp(dot(w2, e2) / dot(e2, e2), 0.0, 1.0);
    vec2 b3 = w3 - e3 * clamp(dot(w3, e3) / dot(e3, e3), 0.0, 1.0);

    float d = min(min(dot2(b0), dot2(b1)), min(dot2(b2), dot2(b3)));

    float s = 1.0;
    bvec3 c0 = bvec3(p.y >= v0.y, p.y < v1.y, e0.x * w0.y > e0.y * w0.x);
    if ((c0.x && c0.y && c0.z) || (!c0.x && !c0.y && !c0.z)) s = -s;
    bvec3 c1 = bvec3(p.y >= v1.y, p.y < v2.y, e1.x * w1.y > e1.y * w1.x);
    if ((c1.x && c1.y && c1.z) || (!c1.x && !c1.y && !c1.z)) s = -s;
    bvec3 c2 = bvec3(p.y >= v2.y, p.y < v3.y, e2.x * w2.y > e2.y * w2.x);
    if ((c2.x && c2.y && c2.z) || (!c2.x && !c2.y && !c2.z)) s = -s;
    bvec3 c3 = bvec3(p.y >= v3.y, p.y < v0.y, e3.x * w3.y > e3.y * w3.x);
    if ((c3.x && c3.y && c3.z) || (!c3.x && !c3.y && !c3.z)) s = -s;

    return s * sqrt(d);
}

// 3D extrusion of 2D SDF with smooth rounded bevel
float opExtrudeRound(float d2d, float z, float halfThick, float roundness) {
    vec2 w = vec2(d2d, abs(z) - (halfThick - roundness));
    return min(max(w.x, w.y), 0.0) + length(max(w, 0.0)) - roundness;
}

// Flutter logo 3D SDF
vec3 mapFlutter(vec3 p, float time) {
    // Idle floating and gentle 3D tilt
    float pitch = sin(time * LOGO_FLOAT_SPEED * 0.9) * 0.12 - 0.14;
    float yaw = cos(time * LOGO_FLOAT_SPEED * 0.8) * 0.16 + 0.24;
    float roll = sin(time * LOGO_FLOAT_SPEED * 0.7) * 0.04 + 0.05;

    p.yz = rot2D(pitch) * p.yz;
    p.xz = rot2D(yaw) * p.xz;
    p.xy = rot2D(roll) * p.xy;

    vec3 lp = p / LOGO_SCALE;

    // Official Flutter geometry vertices (normalized to center (0,0))
    // Piece 1: Top long wing
    vec2 p1_0 = vec2(0.222, 1.111);
    vec2 p1_1 = vec2(0.889, 1.111);
    vec2 p1_2 = vec2(-0.550, -0.328);
    vec2 p1_3 = vec2(-0.889, 0.000);

    // Piece 2: Middle chevron
    vec2 p2_0 = vec2(0.222, 0.086);
    vec2 p2_1 = vec2(0.889, 0.086);
    vec2 p2_2 = vec2(-0.042, -0.844);
    vec2 p2_3 = vec2(-0.381, -0.507);

    // Piece 3: Bottom fold
    vec2 p3_0 = vec2(-0.042, -0.844);
    vec2 p3_1 = vec2(0.296, -0.507);
    vec2 p3_2 = vec2(0.889, -1.111);
    vec2 p3_3 = vec2(0.211, -1.111);

    float d1_2d = sdQuad(lp.xy, p1_0, p1_1, p1_2, p1_3);
    float d2_2d = sdQuad(lp.xy, p2_0, p2_1, p2_2, p2_3);
    float d3_2d = sdQuad(lp.xy, p3_0, p3_1, p3_2, p3_3);

    // 3D depth layering of the pieces (middle folds forward, bottom folds back)
    float d1_3d = opExtrudeRound(d1_2d, lp.z + 0.02, LOGO_THICKNESS, LOGO_ROUNDNESS);
    float d2_3d = opExtrudeRound(d2_2d, lp.z - 0.03, LOGO_THICKNESS, LOGO_ROUNDNESS);
    float d3_3d = opExtrudeRound(d3_2d, lp.z + 0.03, LOGO_THICKNESS, LOGO_ROUNDNESS);

    float dist = min(d1_3d, min(d2_3d, d3_3d)) * LOGO_SCALE;
    return vec3(dist, lp.x, lp.y);
}

vec3 calcNormal(vec3 p, float time) {
    vec2 e = vec2(0.0015, 0.0);
    float d = mapFlutter(p, time).x;
    return normalize(vec3(
        mapFlutter(p + e.xyy, time).x - d,
        mapFlutter(p + e.yxy, time).x - d,
        mapFlutter(p + e.yyx, time).x - d
    ));
}

// Non-repeating saturated spectral rainbow palette across t in [0.0, 1.0]:
// Red -> Orange -> Yellow -> Green -> Cyan -> Blue -> Purple -> Magenta
vec3 saturatedSpectralPalette(float t, float saturation) {
    t = clamp(t, 0.0, 1.0);
    // Smooth spectral sweep: 0.0 (Crimson/Red) -> 0.82 (Deep Violet/Magenta)
    float h = (1.0 - t) * 0.82;
    vec3 kr = mod(vec3(5.0, 3.0, 1.0) + vec3(h * 6.0), vec3(6.0));
    vec3 f = min(kr, vec3(4.0) - kr);
    vec3 rgb = clamp(vec3(1.0) - f, 0.0, 1.0);

    // Saturation enhancement in perceptual luminance space
    float lum = dot(rgb, vec3(0.2126, 0.7152, 0.0722));
    rgb = clamp(mix(vec3(lum), rgb, saturation), 0.0, 1.0);
    return rgb;
}

vec3 toLocalSpace(vec3 p, float time) {
    float pitch = sin(time * LOGO_FLOAT_SPEED * 0.9) * 0.12 - 0.14;
    float yaw = cos(time * LOGO_FLOAT_SPEED * 0.8) * 0.16 + 0.24;
    float roll = sin(time * LOGO_FLOAT_SPEED * 0.7) * 0.04 + 0.05;

    p.yz = rot2D(pitch) * p.yz;
    p.xz = rot2D(yaw) * p.xz;
    p.xy = rot2D(roll) * p.xy;
    return p;
}

vec3 toWorldSpace(vec3 v, float time) {
    float pitch = sin(time * LOGO_FLOAT_SPEED * 0.9) * 0.12 - 0.14;
    float yaw = cos(time * LOGO_FLOAT_SPEED * 0.8) * 0.16 + 0.24;
    float roll = sin(time * LOGO_FLOAT_SPEED * 0.7) * 0.04 + 0.05;

    v.xy = rot2D(-roll) * v.xy;
    v.xz = rot2D(-yaw) * v.xz;
    v.yz = rot2D(-pitch) * v.yz;
    return v;
}

// Sample texture height based on dominant local normal axis (fast triplanar mapping)
float sampleRoughnessHeight(vec3 lp, vec3 ln) {
    vec3 a = abs(ln);
    if (a.x > a.y && a.x > a.z) {
        return texture(iChannel0, lp.yz * ROUGHNESS_SCALE).r;
    } else if (a.y > a.z) {
        return texture(iChannel0, lp.xz * ROUGHNESS_SCALE).r;
    }
    return texture(iChannel0, lp.xy * ROUGHNESS_SCALE).r;
}

// Perturb surface normal using texture height gradient
vec3 applySurfaceRoughness(vec3 pos, vec3 n, float time) {
    if (ROUGHNESS_INTENSITY <= 0.0001) return n;

    vec3 lp = toLocalSpace(pos, time) / LOGO_SCALE;
    vec3 ln = toLocalSpace(n, time);
    float eps = 0.008;

    float h0 = sampleRoughnessHeight(lp, ln);
    float hx = sampleRoughnessHeight(lp + vec3(eps, 0.0, 0.0), ln);
    float hy = sampleRoughnessHeight(lp + vec3(0.0, eps, 0.0), ln);
    float hz = sampleRoughnessHeight(lp + vec3(0.0, 0.0, eps), ln);

    vec3 localGrad = (vec3(hx, hy, hz) - h0) / eps;
    // Project gradient onto surface tangent plane
    localGrad -= dot(localGrad, ln) * ln;

    vec3 worldGrad = toWorldSpace(localGrad, time);
    return normalize(n - worldGrad * ROUGHNESS_INTENSITY);
}

// ACES filmic tone mapping curve
vec3 acesFilm(vec3 x) {
    float a = 2.51;
    float b = 0.03;
    float c = 2.43;
    float d = 0.59;
    float e = 0.14;
    return clamp((x * (a * x + b)) / (x * (c * x + d) + e), 0.0, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / min(iResolution.x, iResolution.y);

    // Interactive mouse rotation
    vec2 m = iMouse.xy / iResolution.xy;
    float mouseYaw = (iMouse.z > 0.0) ? (m.x - 0.5) * 2.8 : 0.0;
    float mousePitch = (iMouse.z > 0.0) ? (m.y - 0.5) * 2.2 : 0.0;

    vec3 ro = vec3(0.0, 0.0, 3.2);
    vec3 rd = normalize(vec3(uv, -2.3));

    ro.xz = rot2D(mouseYaw) * ro.xz;
    rd.xz = rot2D(mouseYaw) * rd.xz;
    ro.yz = rot2D(mousePitch) * ro.yz;
    rd.yz = rot2D(mousePitch) * rd.yz;

    // Studio light setup: Front Key Light, Top-Right Rim Light, Top-Left Rim Light
    vec3 lightPos1 = vec3(0.5, 0.8, 2.2);    // Front Key Light -> bright specular hotspot on glass face!
    vec3 lightPos2 = vec3(1.8, 1.8, 0.5);    // Upper-right rim light
    vec3 lightPos3 = vec3(-1.5, 1.4, -0.4);  // Upper-left rim light

    // Dynamic curvature breathing over time
    float waveTime = iTime * IRID_CURVE_SPEED;
    float dynamicCurvature = IRID_CURVATURE * (1.0 + IRID_CURVE_DYNAMIC * sin(waveTime * 1.2));

    // Sinusoidal back-and-forth horizontal oscillation
    float horizShift = sin(iTime * IRID_HORIZONTAL_SPEED) * IRID_HORIZONTAL_SPAN;

    // 1. Primary raymarch (Front surface)
    float t = 0.8;
    float minD = 10.0;
    vec3 hitData = vec3(0.0);
    bool hit = false;

    for (int i = 0; i < 90; i++) {
        vec3 p = ro + t * rd;
        vec3 res = mapFlutter(p, iTime);
        if (res.x < minD) minD = res.x;
        if (res.x < 0.0012) {
            hit = true;
            hitData = res;
            break;
        }
        t += res.x * 0.82;
        if (t > 6.2) break;
    }

    vec3 col = vec3(0.0);

    if (hit) {
        vec3 pos = ro + t * rd;
        vec3 geoN = calcNormal(pos, iTime);

        // Geometric Fresnel (for smooth macro edge glints)
        float geoNdotv = max(dot(geoN, -rd), 0.0);
        float fresnel = 1.0 - geoNdotv;
        float fresnelPow = pow(fresnel, FRESNEL_POWER);

        // Perturb surface normal using roughness texture on iChannel0
        vec3 n = applySurfaceRoughness(pos, geoN, iTime);

        // Sinusoidal horizontal traveling anisotropic curved wave:
        float xShifted = hitData.y - horizShift;
        float yCoord = hitData.z;
        float uLong = xShifted + yCoord;
        float uTrans = xShifted - yCoord;
        float curveOffset = dynamicCurvature * (uTrans * uTrans);
        float coord = uLong - curveOffset - IRID_SPECTRUM_OFFSET;
        float s = coord / IRID_SPECTRUM_LENGTH + 0.5;
        s += (fresnel - 0.5) * IRID_FRINGE_INTENSITY;

        // Iridescent band mask: 1.0 inside band [0, 1], smoothly 0.0 outside (black transparent glass)
        float iridMask = smoothstep(0.0, IRID_EDGE_FEATHER, s) * (1.0 - smoothstep(1.0 - IRID_EDGE_FEATHER, 1.0, s));
        vec3 irid = saturatedSpectralPalette(s, IRID_SATURATION);

        // Front Key Light (produces localized circular specular hotspot on glass face)
        vec3 l1 = normalize(lightPos1 - pos);
        float diff1 = max(dot(n, l1), 0.0);

        // Rim Lights (produce razor highlights on beveled edges)
        vec3 l2 = normalize(lightPos2 - pos);
        vec3 l3 = normalize(lightPos3 - pos);

        vec3 ref = reflect(rd, n);
        float refl1 = max(dot(ref, l1), 0.0);
        float refl2 = max(dot(ref, l2), 0.0);
        float refl3 = max(dot(ref, l3), 0.0);

        // Spottedness modulator along the glass wings
        float spotWave = sin((hitData.y - hitData.z) * 3.5 + 1.2) * 0.5 + 0.5;
        float spotFactor = pow(spotWave, 2.5);
        float spotMod = (1.0 - HIGHLIGHT_SPOTTEDNESS) + HIGHLIGHT_SPOTTEDNESS * spotFactor * 1.6;

        // Chromatic dispersion exponents for R, G, B channels
        float expR = HIGHLIGHT_SHARPNESS * (1.0 - HIGHLIGHT_DISPERSION);
        float expG = HIGHLIGHT_SHARPNESS;
        float expB = HIGHLIGHT_SHARPNESS * (1.0 + HIGHLIGHT_DISPERSION);

        vec3 specSpot = vec3(
            pow(refl1, expR),
            pow(refl1, expG),
            pow(refl1, expB)
        ) * spotMod * HIGHLIGHT_INTENSITY;

        // Edge bevel rim highlights
        float specRim1 = pow(refl2, 70.0) * 1.8;
        float specRim2 = pow(refl3, 70.0) * 1.6;
        float edgeGlint = fresnelPow * RIM_GLINT_INTENSITY;

        // Glass Fresnel reflectance (Schlick approximation)
        float glassReflectance = 0.04 + 0.96 * fresnelPow;
        float glassTransmission = mix(1.0, glassReflectance, GLASS_TRANSPARENCY);

        // Front body color
        vec3 flutterTint = vec3(0.12, 0.65, 0.98);
        vec3 bodyColor = mix(irid, flutterTint, FLUTTER_TINT_AMOUNT) * iridMask * (0.24 * diff1 + 0.08) * glassTransmission;

        // Front edge rims: colored rainbow inside band, neutral crystalline glints outside band
        vec3 neutralRim = vec3(0.85, 0.92, 1.0);
        vec3 edgeTint = mix(neutralRim, irid, iridMask);
        vec3 edgeCol = edgeGlint * edgeTint;

        // 2. INTERNAL REFRACTED RAYMARCH TO REVEAL BACK EDGES & OVERLAPPING PIECES!
        vec3 rdIn = refract(rd, n, 1.0 / GLASS_REFRACT_INDEX);
        if (dot(rdIn, rdIn) < 0.1) rdIn = ref; // Total internal reflection fallback

        vec3 backCol = vec3(0.0);
        float tIn = 0.02;
        vec3 hitBackData = vec3(0.0);
        bool hitBack = false;

        for (int j = 0; j < 40; j++) {
            vec3 pIn = pos + tIn * rdIn;
            vec3 resIn = mapFlutter(pIn, iTime);
            if (abs(resIn.x) < 0.0025 && tIn > 0.035) {
                hitBack = true;
                hitBackData = resIn;
                break;
            }
            float stepIn = max(0.009, abs(resIn.x) * 0.75);
            tIn += stepIn;
            if (tIn > 0.48) {
                hitBack = true;
                hitBackData = resIn;
                break;
            }
        }

        if (hitBack) {
            vec3 posBack = pos + tIn * rdIn;
            vec3 nBack = calcNormal(posBack, iTime);
            float bNdotv = max(abs(dot(nBack, rdIn)), 0.0);
            float fresnelBack = pow(1.0 - bNdotv, 3.5);

            float bxShifted = hitBackData.y - horizShift;
            float byCoord = hitBackData.z;
            float buLong = bxShifted + byCoord;
            float buTrans = bxShifted - byCoord;
            float bCoord = buLong - dynamicCurvature * (buTrans * buTrans) - IRID_SPECTRUM_OFFSET;
            float bs = bCoord / IRID_SPECTRUM_LENGTH + 0.5;
            float bMask = smoothstep(0.0, IRID_EDGE_FEATHER, bs) * (1.0 - smoothstep(1.0 - IRID_EDGE_FEATHER, 1.0, bs));
            vec3 bIrid = saturatedSpectralPalette(bs, IRID_SATURATION);

            // Back edge highlight glints
            float bRefl = max(dot(rdIn, l2), 0.0);
            float bSpec = pow(bRefl, 50.0) * 1.5;
            float backEdgeGlint = (fresnelBack * BACK_EDGE_INTENSITY + bSpec);
            vec3 bTint = mix(neutralRim, bIrid, bMask);

            float transFactor = GLASS_TRANSPARENCY * (1.0 - fresnel * 0.85);
            backCol = backEdgeGlint * bTint * transFactor;
        }

        // Specular glints composite with chromatic dispersion
        vec3 totalRim = (specRim1 + specRim2) * neutralRim;
        vec3 specCol = specSpot + totalRim;

        col = bodyColor + edgeCol + backCol + specCol;

        // Depth distance fade into darkness
        float fade = clamp((5.4 - t) / 2.0, 0.0, 1.0);
        col *= fade;
    } else {
        // Soft iridescent & Flutter cyan corona in deep OLED black (only around active curved band)
        float glow = exp(-minD * CORONA_FALLOFF) * CORONA_BLOOM_GLOW;
        float gxShifted = uv.x - horizShift;
        float gyCoord = uv.y;
        float uLongGlow = gxShifted + gyCoord;
        float uTransGlow = gxShifted - gyCoord;
        float coordGlow = uLongGlow - dynamicCurvature * (uTransGlow * uTransGlow) * 0.5 - IRID_SPECTRUM_OFFSET;
        float sGlow = coordGlow / IRID_SPECTRUM_LENGTH + 0.5;
        float iridMaskGlow = smoothstep(0.0, IRID_EDGE_FEATHER * 2.0, sGlow) * (1.0 - smoothstep(1.0 - IRID_EDGE_FEATHER * 2.0, 1.0, sGlow));
        vec3 glowCol = saturatedSpectralPalette(sGlow, IRID_SATURATION);
        col = glow * glowCol * iridMaskGlow;
    }

    // Filmic tone mapping & gamma correction
    col = acesFilm(col);
    col = pow(col, vec3(1.0 / 2.2));

    fragColor = vec4(col, 1.0);
}
